def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width and full-height divider lines.
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_ranges = []
    start = 0
    for r in div_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in div_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    # The most common non-divider color is the tile background.
    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r0, r1 in row_ranges
        for c0, c1 in col_ranges
        for r in range(r0, r1)
        for c in range(c0, c1)
    )
    background = counts.most_common(1)[0][0]

    result = []
    for r0, r1 in row_ranges:
        out_row = []
        for c0, c1 in col_ranges:
            marks = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            out_row.append(1 if marks == 2 else background)
        result.append(out_row)
    return result
